function extFor(name) { const m = (name || "").toLowerCase().match(/\.[a-z0-9]+$/); return m ? m[0] : ".aac"; }
function parsePhoneName(name) {
  const s = String(name || "");
  let m = s.match(/\+?998\d{9}/); if (m) return m[0].replace("+", "");
  const g = s.match(/(?<!\d)\d{9,12}(?!\d)/g);
  return g && g.length ? g[g.length - 1] : "";
}
function mimeFor(name) {
  const n = (name || "").toLowerCase();
  if (n.endsWith(".mp3")) return "audio/mp3";
  if (n.endsWith(".wav")) return "audio/wav";
  if (n.endsWith(".ogg") || n.endsWith(".opus")) return "audio/ogg";
  if (n.endsWith(".m4a") || n.endsWith(".mp4")) return "audio/mp4";
  if (n.endsWith(".aac")) return "audio/aac";
  if (n.endsWith(".flac")) return "audio/flac";
  if (n.endsWith(".amr") || n.endsWith(".3gp")) return "audio/amr";
  return "audio/aac";
}
// Fayl ICHIDAGI baytlardan haqiqiy formatni aniqlash (kengaytmaga ishonmaymiz —
// Automate'дан kelган yozuvlar ko'pincha noto'g'ri nom bilan keladi).
function sniffMime(buf, fallbackName) {
  if (!buf || buf.length < 12) return mimeFor(fallbackName);
  const a = buf.slice(0, 16);
  const s = (o, n) => a.slice(o, o + n).toString("latin1");
  if (s(4, 4) === "ftyp") return "audio/mp4";                 // m4a / mp4 (Samsung call recording)
  if (s(0, 4) === "RIFF" && s(8, 4) === "WAVE") return "audio/wav";
  if (s(0, 4) === "OggS") return "audio/ogg";
  if (s(0, 4) === "fLaC") return "audio/flac";
  if (s(0, 3) === "ID3") return "audio/mp3";
  if (s(0, 5) === "#!AMR") return "audio/amr";
  if (a[0] === 0xff && (a[1] & 0xe0) === 0xe0) {              // MPEG audio / ADTS
    if ((a[1] & 0x16) === 0x02 || (a[1] & 0x16) === 0x00) {} // (belgi uchun)
    return (a[1] & 0x08) ? "audio/mp3" : "audio/aac";        // MPEG-1 layer bit
  }
  return mimeFor(fallbackName);
}
// Gemini uchun sinab ko'riladigan MIME variantlari (INVALID_ARGUMENT bo'lса keyingisi)
function mimeCandidates(buf, name) {
  const first = sniffMime(buf, name);
  const all = [first, "audio/mp4", "audio/aac", "audio/mp3", "audio/wav", "audio/ogg"];
  const out = []; all.forEach((m) => { if (out.indexOf(m) < 0) out.push(m); });
  return out;
}

