const TESTPAGE = "<!doctype html><html lang=\"uz\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Telefon simulyatori</title>\n<style>\n:root{--bg:#eef1f6;--surface:#fff;--surface-2:#f6f8fb;--line:#e2e7f0;--ink:#141821;--muted:#5b6473;--faint:#8a93a4;--brand:#2757d6;--good:#15a24a;--good-soft:#e2f6e9;--amber:#e08600;--amber-soft:#fdf0d8;--bad:#dc3546;--bad-soft:#fde5e7;--shadow:0 1px 2px rgba(20,24,33,.04),0 6px 20px rgba(20,24,33,.06)}\n@media (prefers-color-scheme:dark){:root{--bg:#0d1017;--surface:#161b24;--surface-2:#1d232e;--line:#2a3240;--ink:#eef2f8;--muted:#9aa4b4;--faint:#6b7688;--brand:#5c86f5;--good:#3ad07a;--good-soft:#12301f;--amber:#f6ad3c;--amber-soft:#352a10;--bad:#ff6b78;--bad-soft:#3a1a1e;--shadow:0 1px 2px rgba(0,0,0,.3),0 6px 20px rgba(0,0,0,.35)}}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,system-ui,sans-serif;font-size:14px;line-height:1.5}\n.wrap{max-width:560px;margin:0 auto;padding:16px 16px 40px}\nh1{font-size:19px;margin:0 0 2px}.sub{font-size:12.5px;color:var(--muted)}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);padding:14px;margin-top:12px}\n.step{font-size:11px;font-weight:800;color:var(--brand);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px}\ninput[type=file]{width:100%;padding:11px;border-radius:11px;border:1.5px dashed var(--line);background:var(--surface-2);color:var(--ink);font-size:14px}\n.btn{width:100%;padding:13px;border:none;border-radius:12px;background:var(--brand);color:#fff;font-weight:700;font-size:15px;cursor:pointer;margin-top:10px}\n.btn.ghost{background:var(--surface-2);color:var(--ink);border:1px solid var(--line);font-size:13.5px}\n.btn:disabled{opacity:.55}\n.kv{display:grid;grid-template-columns:110px 1fr;gap:4px 10px;font-size:13px;margin-top:8px}.kv div:nth-child(odd){color:var(--muted)}\n.log{font-size:13px;margin-top:4px}.log div{padding:6px 0;border-bottom:1px solid var(--line)}.log div:last-child{border:none}\n.ok{color:var(--good);font-weight:700}.bad{color:var(--bad);font-weight:700}.wait{color:var(--amber);font-weight:700}\n.res{border-radius:12px;padding:12px;margin-top:10px}\n.score{font-size:30px;font-weight:800;font-family:Georgia,serif}\na{color:var(--brand);font-weight:700}\n.spin{width:14px;height:14px;border:2px solid var(--amber-soft);border-top-color:var(--amber);border-radius:50%;animation:sp .8s linear infinite;display:inline-block;vertical-align:-2px}\n@keyframes sp{to{transform:rotate(360deg)}}\n</style></head><body><div class=\"wrap\">\n<h1>📱 Telefon simulyatori</h1>\n<div class=\"sub\">Telefon (Automate) qo'ng'iroq tugagach serverga nima yuborsa, bu sahifa ham aynan shuni yuboradi. Telefonga tegmasdan butun tizimni sinab ko'rish uchun.</div>\n\n<div class=\"card\">\n  <div class=\"step\">1-qadam · Yozuvni tanlang</div>\n  <input type=\"file\" id=\"f\" accept=\"audio/*,.m4a,.amr,.3gp\">\n  <div id=\"info\" class=\"kv\" style=\"display:none\"></div>\n</div>\n\n<div class=\"card\">\n  <div class=\"step\">2-qadam · Yuborish</div>\n  <button class=\"btn\" id=\"goGood\" disabled>✅ Telefondek yuborish (yangi sozlama)</button>\n  <div class=\"sub\" style=\"margin-top:6px\">Qo'ng'iroq tugagach to'liq fayl + fayl nomi yuboriladi.</div>\n  <button class=\"btn ghost\" id=\"goBad\" disabled>⚠️ Eski xatoni takrorlash (bo'sh fayl)</button>\n  <div class=\"sub\" style=\"margin-top:6px\">Eski sozlamada telefon qo'ng'iroq boshida ~5 KB bo'sh fayl yuborardi. Server uni endi rad etishi kerak.</div>\n</div>\n\n<div class=\"card\" id=\"logCard\" style=\"display:none\">\n  <div class=\"step\">3-qadam · Natija</div>\n  <div class=\"log\" id=\"log\"></div>\n  <div id=\"result\"></div>\n</div>\n<div class=\"sub\" style=\"text-align:center;margin-top:16px\"><a href=\"/\">← Asosiy sahifaga qaytish</a></div>\n</div>\n<script>\nvar TOKEN=\"temirchi123\",PATH=\"/storage/emulated/0/Recordings/Call/\";\nvar STLAB={sotildi:\"✅ Sotildi\",ikkilandi:\"⏳ Ikkilandi\",qayta:\"🔁 Qayta qo'ng'iroq\",yoq:\"❌ Yo'q\",gaplashildi:\"Gaplashildi\"};\nvar CATN={mijoz:\"🤝 Mijoz\",uy:\"🏠 Uy\",shofir:\"🚚 Shofir\",usta:\"🔧 Usta\",boshqa:\"💬 Boshqa\"};\nfunction $(i){return document.getElementById(i);}\nfunction esc(s){return String(s==null?\"\":s).replace(/[&<>\"]/g,function(c){return{\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",\"\\\"\":\"&quot;\"}[c];});}\nfunction kb(n){return n>=1048576?(n/1048576).toFixed(1)+\" MB\":Math.max(1,Math.round(n/1024))+\" KB\";}\nfunction phoneOf(n){var m=n.match(/\\+?998\\d{9}/);if(m)return m[0].replace(\"+\",\"\");var g=n.match(/\\d{9,12}/g);return g?g[g.length-1]:\"\";}\nfunction log(html,cls){$(\"logCard\").style.display=\"block\";var d=document.createElement(\"div\");d.innerHTML=(cls?'<span class=\"'+cls+'\">':'<span>')+html+'</span>';$(\"log\").appendChild(d);return d;}\n$(\"f\").onchange=function(){\n  var f=this.files[0];if(!f)return;var ph=phoneOf(f.name);\n  $(\"info\").style.display=\"grid\";\n  $(\"info\").innerHTML='<div>Fayl</div><div>'+esc(f.name)+'</div><div>Hajmi</div><div>'+kb(f.size)+'</div><div>Raqam</div><div>'+(ph?'<b>'+ph+'</b> (nomdan olindi)':'<span class=\"bad\">nomda raqam yo\\'q</span>')+'</div>';\n  $(\"goGood\").disabled=false;$(\"goBad\").disabled=false;\n};\nfunction reset(){$(\"log\").innerHTML=\"\";$(\"result\").innerHTML=\"\";}\n$(\"goGood\").onclick=function(){\n  var f=$(\"f\").files[0];if(!f)return;reset();var b=this;b.disabled=true;\n  var url=\"/api/upload-raw?token=\"+TOKEN+\"&name=\"+encodeURIComponent(PATH+f.name);\n  log(\"📤 Telefon yuboryapti: \"+esc(f.name)+\" (\"+kb(f.size)+\")\");\n  fetch(url,{method:\"POST\",headers:{\"Content-Type\":\"application/octet-stream\"},body:f}).then(function(r){return r.json().then(function(j){return{s:r.status,j:j};});}).then(function(x){\n    if(x.s!==200){log(\"✕ Server rad etdi: \"+esc(x.j.error||x.s),\"bad\");b.disabled=false;return;}\n    if(x.j.status===\"duplicate\"){log(\"ℹ️ Bu fayl avval yuborilgan — dublikat yaratilmadi ✓\",\"ok\");poll(x.j.id,b);return;}\n    log(\"✓ Server qabul qildi\",\"ok\");\n    var w=log('<span class=\"spin\"></span> AI eshitib, tahlil qilyapti... (20–60 soniya)',\"wait\");w.id=\"wline\";\n    poll(x.j.id,b);\n  }).catch(function(e){log(\"✕ Ulanish xatosi: \"+esc(e.message),\"bad\");b.disabled=false;});\n};\n$(\"goBad\").onclick=function(){\n  var f=$(\"f\").files[0];if(!f)return;reset();var b=this;b.disabled=true;\n  var stub=f.slice(0,4888);\n  log(\"📤 Eski sozlama: qo'ng'iroq boshida bo'sh fayl yuborilyapti (4.8 KB, nomsiz)\");\n  fetch(\"/api/upload-raw?token=\"+TOKEN,{method:\"POST\",headers:{\"Content-Type\":\"application/octet-stream\"},body:stub}).then(function(r){return r.json().then(function(j){return{s:r.status,j:j};});}).then(function(x){\n    if(x.j&&x.j.skipped)log(\"✓ Server bo'sh faylni rad etdi — ro'yxatda xato kartochka chiqmaydi. To'g'ri ishlayapti.\",\"ok\");\n    else if(x.s===200)log(\"✕ Server bo'sh faylni qabul qilib qo'ydi — server.js eski versiyada (yangisini yuklang)\",\"bad\");\n    else log(\"Server javobi: \"+esc((x.j&&x.j.error)||x.s));\n    b.disabled=false;\n  }).catch(function(e){log(\"✕ Ulanish xatosi: \"+esc(e.message),\"bad\");b.disabled=false;});\n};\nfunction poll(id,b){\n  fetch(\"/api/calls/\"+id).then(function(r){return r.json();}).then(function(c){\n    if(c.procStatus===\"processing\"){setTimeout(function(){poll(id,b);},3000);return;}\n    var w=$(\"wline\");if(w)w.remove();b.disabled=false;\n    if(c.procStatus===\"error\"){log(\"✕ AI tahlil qila olmadi: \"+esc(String(c.error||\"\").slice(0,200)),\"bad\");return;}\n    log(\"✓ AI tahlil qildi — dashboardga tushdi\",\"ok\");\n    var a=c.analysis||{},s=a.overall,col=s>=70?\"var(--good)\":s>=45?\"var(--amber)\":\"var(--bad)\",soft=s>=70?\"var(--good-soft)\":s>=45?\"var(--amber-soft)\":\"var(--bad-soft)\";\n    var h='<div class=\"res\" style=\"background:'+(s!=null?soft:\"var(--surface-2)\")+'\"><div style=\"display:flex;justify-content:space-between;align-items:center;gap:10px\"><div><div style=\"font-weight:800;font-size:15px\">📞 '+esc(c.phone||\"raqamsiz\")+'</div><div class=\"sub\">'+(CATN[c.category]||c.category)+(c.category===\"mijoz\"?' · '+(STLAB[c.status]||c.status):'')+'</div></div>'+(s!=null?'<div class=\"score\" style=\"color:'+col+'\">'+s+'</div>':'')+'</div></div>';\n    h+='<div class=\"kv\">';\n    if(c.product)h+='<div>Mahsulot</div><div>📦 '+esc(c.product)+'</div>';\n    if(c.lostReason)h+='<div>Sabab</div><div style=\"color:var(--bad)\">'+esc(c.lostReason)+'</div>';\n    if(a.nextDate)h+='<div>Eslatma</div><div>⏰ '+esc(a.nextAction||\"\")+' — '+esc(String(a.nextDate).replace(\"T\",\" \"))+'</div>';\n    h+='<div>AI xulosa</div><div>'+esc(a.summary||\"\")+'</div></div>';\n    h+='<a class=\"btn\" style=\"display:block;text-align:center;text-decoration:none\" href=\"/\">Dashboardda ko\\'rish →</a>';\n    $(\"result\").innerHTML=h;\n  }).catch(function(){setTimeout(function(){poll(id,b);},4000);});\n}\n</script></body></html>\n";
