// --- Yuklash (raw, Automate uchun) ---
app.post("/api/upload-raw", express.raw({ type: "*/*", limit: "60mb" }), async (req, res) => {
  try {
    const token = req.query.token || (req.headers.authorization || "").replace("Bearer ", "");
    if (token !== TOKEN) return res.status(401).json({ error: "noto'g'ri token" });
    if (!API_KEY && !PROJECT) return res.status(500).json({ error: "Gemini sozlanmagan" });
    if (!req.body || !req.body.length) return res.status(400).json({ error: "audio yo'q" });
    // Yozuv hali tugamagan (bo'sh) bo'lsa — qabul qilmaymiz, keraksiz xato kartochka chiqmasin
    if (req.body.length < MIN_AUDIO) return res.status(400).json({ error: "yozuv juda kichik (" + req.body.length + " bayt) — qo'ng'iroq hali tugamagan", skipped: true });
    const rawName = req.query.name || req.headers["x-filename"] || "";
    const name = rawName ? path.basename(String(rawName)) : ("yozuv_" + Date.now() + ".m4a");
    // Bir xil fayl ikki marta kelsa — dublikat qilmaymiz (kattaroq bo'lsa yangilaymiz)
    if (rawName) {
      const db = load(); const ex = db.calls.find((c) => c.audioName === name);
      if (ex) {
        if ((ex.audioSize || 0) >= req.body.length && ex.procStatus !== "error") return res.json({ id: ex.id, status: "duplicate" });
        try { fs.writeFileSync(path.join(AUDIO_DIR, ex.audioFile), req.body); } catch (e) {}
        ex.audioSize = req.body.length; ex.procStatus = "processing"; ex.error = null; save(db);
        res.json({ id: ex.id, status: "processing" });
        return processCall(ex.id, req.body, mimeFor(name)).catch((e) => markError(ex.id, e.message));
      }
    }
    const id = ingest(req.body, name, req.query);
    res.json({ id, status: "processing" });
    processCall(id, req.body, mimeFor(name)).catch((e) => markError(id, e.message));
  } catch (e) { console.error(e); res.status(500).json({ error: e.message }); }
});

